59	export function getByRoleSelector(role: string, options: ByRoleOptions = {}): string {
60	  const props: string[][] = [];
61	  if (options.checked !== undefined)
62	    props.push(['checked', String(options.checked)]);
63	  if (options.disabled !== undefined)
64	    props.push(['disabled', String(options.disabled)]);
65	  if (options.selected !== undefined)
66	    props.push(['selected', String(options.selected)]);
67	  if (options.expanded !== undefined)
68	    props.push(['expanded', String(options.expanded)]);
69	  if (options.includeHidden !== undefined)
70	    props.push(['include-hidden', String(options.includeHidden)]);
71	  if (options.level !== undefined)
72	    props.push(['level', String(options.level)]);
