504	export function getElementAccessibleName(element: Element, includeHidden: boolean): string {
505	  const cache = (includeHidden ? cacheAccessibleNameHidden : cacheAccessibleName);
506	  let accessibleName = cache?.get(element);
507	
508	  if (accessibleName === undefined) {
509	    // https://w3c.github.io/accname/#computation-steps
510	    accessibleName = '';
511	
512	    // step 1.
513	    // https://w3c.github.io/aria/#namefromprohibited
514	    const elementProhibitsNaming = ['caption', 'code', 'definition', 'deletion', 'emphasis', 'generic', 'insertion', 'mark', 'paragraph', 'presentation', 'strong', 'subscript', 'suggestion', 'superscript', 'term', 'time'].includes(getAriaRole(element) || '');
515	
516	    if (!elementProhibitsNaming) {
517	      // step 2.
518	      accessibleName = asFlatString(getTextAlternativeInternal(element, {
519	        includeHidden,
520	        visitedElements: new Set(),
521	        embeddedInTargetElement: 'self',
522	      }));
523	    }
524	
525	    cache?.set(element, accessibleName);
526	  }
527	  return accessibleName;
528	}
