530	export function getElementAccessibleDescription(element: Element, includeHidden: boolean): string {
531	  const cache = (includeHidden ? cacheAccessibleDescriptionHidden : cacheAccessibleDescription);
532	  let accessibleDescription = cache?.get(element);
533	
534	  if (accessibleDescription === undefined) {
535	    // https://w3c.github.io/accname/#mapping_additional_nd_description
536	    // https://www.w3.org/TR/html-aam-1.0/#accdesc-computation
537	    accessibleDescription = '';
538	
539	    if (element.hasAttribute('aria-describedby')) {
540	      // precedence 1
541	      const describedBy = getIdRefs(element, element.getAttribute('aria-describedby'));
542	      accessibleDescription = asFlatString(describedBy.map(ref => getTextAlternativeInternal(ref, {
543	        includeHidden,
544	        visitedElements: new Set(),
545	        embeddedInDescribedBy: { element: ref, hidden: isElementHiddenForAria(ref) },
546	      })).join(' '));
547	    } else if (element.hasAttribute('aria-description')) {
548	      // precedence 2
549	      accessibleDescription = asFlatString(element.getAttribute('aria-description') || '');
550	    } else {
551	      // TODO: handle precedence 3 - html-aam-specific cases like table>caption.
552	      // https://www.w3.org/TR/html-aam-1.0/#accdesc-computation
553	      // precedence 4
554	      accessibleDescription = asFlatString(element.getAttribute('title') || '');
555	    }
556	
557	    cache?.set(element, accessibleDescription);
558	  }
559	  return accessibleDescription;
560	}
